import (
	"fmt"
)

resp, err := client.CustomerPortalSettings().GetCustomerPortal(ctx, nil, nil)
if err != nil {
	log.Fatal(err)
}
body := resp.Map().(map[string]any)
settings := body["customer_portal"].(map[string]any)
fmt.Println(settings["portal"].(map[string]any)["enabled"], settings["login"].(map[string]any)["registration_link"])
for section, meta := range body["group_meta"].(map[string]any) {
	fmt.Println(section, meta.(map[string]any)["writable"])
}

