	"fmt"
)

resp, err := client.CustomerPortalSettings().PatchCustomerPortal(ctx, map[string]any{
	"customer_portal": map[string]any{
		"login": map[string]any{"registration_link": false},
		"sso":   map[string]any{"azure_ad": map[string]any{"data_mapping": map[string]any{"city": "city"}}},
	},
}, nil)
if err != nil {
	log.Fatal(err)
}
settings := resp.Map().(map[string]any)["customer_portal"].(map[string]any)
mapping := settings["sso"].(map[string]any)["azure_ad"].(map[string]any)["data_mapping"].(map[string]any)
fmt.Println(settings["login"].(map[string]any)["registration_link"], mapping["city"])

